// Wraps TypeScript's CommonJS build (node_modules/typescript/lib/typescript.js)
// as an ES module that Nona can compile: `loadTypeScript()` evaluates it with a
// small `require` that hands it Nona's `node:fs` and `node:path`.
//
//   node wrap-typescript.mjs <path to typescript.js> [out.mjs]
import {readFileSync, writeFileSync} from 'node:fs';

const [input, output = 'typescript.generated.mjs'] = process.argv.slice(2);
if (!input) { console.error('usage: wrap-typescript.mjs <typescript.js> [out.mjs]'); process.exit(2); }
const source = readFileSync(input, 'utf8');
if (!source.includes('var ts = {}; ((module) => {')) throw new Error('unexpected typescript.js layout');
const head = `// Generated by wrap-typescript.mjs from ${input.replace(/\\/g, '/').split('/').slice(-4).join('/')}. Do not edit.
import * as fs from 'node:fs';
import * as path from 'node:path';
export function loadTypeScript() {
  const os = {EOL: '\\n', platform: () => process.platform, cpus: () => []};
  const require = name => {
    switch (name) {
      case 'fs': return fs;
      case 'path': return path;
      case 'os': return os;
      case 'crypto': return {};
      case 'perf_hooks': return {performance: globalThis.performance};
      default: throw new Error('Cannot find module ' + name);
    }
  };
  const module = undefined, __filename = '/typescript/lib/typescript.js', __dirname = '/typescript/lib';
`;
writeFileSync(output, head + source.replace(/\n\/\/# sourceMappingURL=.*\s*$/, '\n') + '\nreturn ts;\n}\n');
console.log(`wrote ${output}`);
